CREATE TYPE public.app_role AS ENUM ('admin','manager','staff');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_manager_or_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','manager')) $$;
CREATE POLICY "read own roles or admin" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,full_name text NOT NULL,department text NOT NULL DEFAULT '',position text NOT NULL DEFAULT '',monthly_target bigint NOT NULL DEFAULT 0,user_id uuid UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),team text NOT NULL DEFAULT '',team_role text NOT NULL DEFAULT 'member',CONSTRAINT employees_team_role_valid CHECK(team_role IN ('leader','member')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role;
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE POLICY "employees read" ON public.employees FOR SELECT TO authenticated USING(true);
CREATE POLICY "employees insert" ON public.employees FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "employees update" ON public.employees FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "employees delete" ON public.employees FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX employees_team_idx ON public.employees(team);
CREATE FUNCTION public.current_employee_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.employees WHERE user_id=auth.uid() LIMIT 1 $$;
CREATE FUNCTION public.can_read_employee(_employee_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_manager_or_admin(auth.uid()) OR _employee_id=public.current_employee_id() OR EXISTS(SELECT 1 FROM public.employees leader JOIN public.employees member ON member.team=leader.team WHERE leader.user_id=auth.uid() AND leader.team_role='leader' AND btrim(leader.team)<>'' AND member.id=_employee_id) $$;
REVOKE ALL ON FUNCTION public.can_read_employee(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_employee(uuid) TO authenticated,service_role;
CREATE TABLE public.sales_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_date date NOT NULL DEFAULT current_date,voucher_no text NOT NULL UNIQUE,employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,customer text NOT NULL DEFAULT '',project text NOT NULL DEFAULT '',gross bigint NOT NULL DEFAULT 0,discount bigint NOT NULL DEFAULT 0,accessories bigint NOT NULL DEFAULT 0,vat bigint NOT NULL DEFAULT 0,kts_commission bigint NOT NULL DEFAULT 0,project_cost bigint NOT NULL DEFAULT 0,nature text NOT NULL DEFAULT 'ca_nhan',deposit bigint NOT NULL DEFAULT 0,due_date date NOT NULL DEFAULT(current_date+30),debt_status text NOT NULL DEFAULT 'chua_thanh_toan',created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sales_records TO authenticated; GRANT ALL ON public.sales_records TO service_role;
ALTER TABLE public.sales_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "records read" ON public.sales_records FOR SELECT TO authenticated USING(public.can_read_employee(employee_id));
CREATE POLICY "records insert" ON public.sales_records FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR(NOT public.has_role(auth.uid(),'manager') AND employee_id=public.current_employee_id()));
CREATE POLICY "records update" ON public.sales_records FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR(NOT public.has_role(auth.uid(),'manager') AND employee_id=public.current_employee_id())) WITH CHECK(public.has_role(auth.uid(),'admin') OR(NOT public.has_role(auth.uid(),'manager') AND employee_id=public.current_employee_id()));
CREATE POLICY "records delete" ON public.sales_records FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin') OR(NOT public.has_role(auth.uid(),'manager') AND employee_id=public.current_employee_id()));
CREATE TABLE public.kpi_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid REFERENCES public.employees(id),target_year integer NOT NULL,period text NOT NULL,period_no integer NOT NULL DEFAULT 1,amount bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT kpi_year_range CHECK(target_year BETWEEN 2000 AND 2200),CONSTRAINT kpi_nonnegative CHECK(amount>=0),CONSTRAINT kpi_period_valid CHECK((period='month' AND period_no BETWEEN 1 AND 12) OR(period='quarter' AND period_no BETWEEN 1 AND 4) OR(period='year' AND period_no=1)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kpi_targets TO authenticated; GRANT ALL ON public.kpi_targets TO service_role;
ALTER TABLE public.kpi_targets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "kpi read" ON public.kpi_targets FOR SELECT TO authenticated USING(public.can_read_employee(employee_id));
CREATE POLICY "kpi admin write" ON public.kpi_targets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX kpi_target_period_unique ON public.kpi_targets(COALESCE(employee_id,'00000000-0000-0000-0000-000000000000'::uuid),target_year,period,period_no);
CREATE FUNCTION public.handle_new_user_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(741960); IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='admin') THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin'); ELSE INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'staff'); END IF; RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created_role AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user_role();
CREATE FUNCTION public.admin_list_users() RETURNS TABLE(user_id uuid,email text,role public.app_role,employee_id uuid) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN QUERY SELECT u.id,u.email::text,(SELECT r.role FROM public.user_roles r WHERE r.user_id=u.id ORDER BY CASE r.role WHEN 'admin' THEN 1 WHEN 'manager' THEN 2 ELSE 3 END LIMIT 1),(SELECT e.id FROM public.employees e WHERE e.user_id=u.id LIMIT 1) FROM auth.users u ORDER BY u.created_at; END $$;
CREATE FUNCTION public.admin_set_role(_user_id uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _user_id=auth.uid() AND _role<>'admin' THEN RAISE EXCEPTION 'Không thể tự hạ quyền Admin'; END IF; DELETE FROM public.user_roles WHERE user_id=_user_id; INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,_role); END $$;
CREATE FUNCTION public.admin_link_employee(_user_id uuid,_employee_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.employees SET user_id=NULL WHERE user_id=_user_id; IF _employee_id IS NOT NULL THEN UPDATE public.employees SET user_id=_user_id WHERE id=_employee_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_list_users(),public.admin_set_role(uuid,public.app_role),public.admin_link_employee(uuid,uuid),public.handle_new_user_role() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_list_users(),public.admin_set_role(uuid,public.app_role),public.admin_link_employee(uuid,uuid) TO authenticated,service_role;
COMMENT ON COLUMN public.employees.monthly_target IS 'Legacy fallback for employee KPI when no independently configured period target exists.';